-- Import of "مطالبات (4).xlsx" into public.claims / public.claim_installments
-- Generated 2026-10-25T12:20:47.131Z
-- Expected: 275 claims, 43 installments

BEGIN;

-- Safety check: the claims section must be empty before this import.
DO $$
DECLARE n bigint;
BEGIN
  SELECT count(*) INTO n FROM public.claims;
  IF n <> 0 THEN
    RAISE EXCEPTION 'Aborting: public.claims is not empty (% rows).', n;
  END IF;
END $$;

CREATE TEMP TABLE _claims_import (
  sheet_name text, row_number integer, data jsonb, claimant_name text, claim_number text,
  claim_date date, amount numeric, status text, notes text, file_name text, pdf_url text,
  payment_status text, total_amount numeric, paid_amount numeric, remaining_amount numeric,
  started_at timestamptz, settled_at timestamptz, settlement_reason text, settlement_notes text,
  installments jsonb
) ON COMMIT DROP;


SELECT sheet_name, row_number, data, claimant_name, claim_number, claim_date, amount, status, notes, file_name, pdf_url, payment_status, total_amount, paid_amount, remaining_amount, started_at, settled_at, settlement_reason, settlement_notes FROM _claims_import;

SELECT c.id, (i->>'number')::int, (i->>'amount')::numeric, (i->>'paid')::boolean, NULLIF(i->>'paid_at','')::timestamptz, NULLIF(i->>'receipt_number','')
FROM _claims_import ci
JOIN public.claims c ON c.sheet_name = ci.sheet_name AND c.row_number = ci.row_number
CROSS JOIN LATERAL jsonb_array_elements(ci.installments) i;

DO $$
DECLARE
  v_claims bigint; v_inst bigint; v_total numeric; v_paid numeric; v_remaining numeric;
BEGIN
  SELECT count(*) INTO v_claims FROM public.claims;
  SELECT count(*) INTO v_inst FROM public.claim_installments;
  SELECT COALESCE(sum(total_amount),0), COALESCE(sum(paid_amount),0), COALESCE(sum(remaining_amount),0) INTO v_total, v_paid, v_remaining FROM public.claims;
  IF v_claims <> 275 THEN RAISE EXCEPTION 'Claim count mismatch: % (expected 275)', v_claims; END IF;
  IF v_inst <> 43 THEN RAISE EXCEPTION 'Installment count mismatch: % (expected 43)', v_inst; END IF;
  IF round(v_total,2) <> 36905134.86 THEN RAISE EXCEPTION 'Total amount mismatch: %', v_total; END IF;
  IF round(v_paid,2) <> 23538720.37 THEN RAISE EXCEPTION 'Paid amount mismatch: %', v_paid; END IF;
  IF round(v_remaining,2) <> 13366414.49 THEN RAISE EXCEPTION 'Remaining amount mismatch: %', v_remaining; END IF;
  RAISE NOTICE 'Import OK: % claims, % installments, total=%, paid=%, remaining=%', v_claims, v_inst, v_total, v_paid, v_remaining;
END $$;

COMMIT;
